 ],
 "lean_claims": [
  {"theorem": "stmt", "line": 6, "plain": "Let X be a proper pseudometric space, let s ⊆ X be bounded, and let x : ℕ → X satisfy x n ∈ s for all n. Then there exist a ∈ closure s and a strictly increasing φ : ℕ → ℕ such that x(φ(n)) → a as n → ∞."}
 ],
 "paper_claims": [
  {"ref": "Theorem (Bolzano-Weierstrass)", "plain": "Every bounded sequence in ℝⁿ has a convergent subsequence, and its limit lies in the closure of the set containing the sequence."}
